        + [M("What is the flight number in the captain’s announcement?", "one-oh-four", ["one-oh-five", "four hundred", "fifteen"], "isa sero apat."), M("At what altitude is the plane flying?", "33,000 feet", ["15,000 feet", "400 feet", "13,000 feet"], "tatlumpu’t tatlong libong talampakan."), M("How fast is the plane flying?", "400 miles per hour", ["104 miles per hour", "33 miles per hour", "15 miles per hour"], "apatnaraang milya."), M("How early will the plane land?", "about fifteen minutes", ["about thirty minutes", "about an hour", "it will be late"], "labinlimang minuto."), M("Who is Romeo Magtalas?", "the aunt’s godson who works at lost and found", ["a pilot", "an immigration officer", "the caller’s husband"], "inaanak."), M("Where did the caller arrive from?", "Cotabato", ["Cebu", "Davao", "San Francisco"], "Cotabato."), M("What does the aunt tell the caller to do?", "go to lost and found and ask for Romeo", ["call the police", "buy a new bag", "go home"], "pumunta ka."), M("When does the passport expire in passage 2?", "on December twentieth", ["next year", "tomorrow", "in a week"], "sa Disyembre a-beynte."), M("How long will the traveler stay in the Philippines?", "until New Year", ["a week", "two years", "a day"], "hanggang bagong taon."), M("Which IDs does the traveler have?", "company ID and driver’s license", ["a student ID only", "a voter’s ID only", "none"], "ID ng kumpanya at driver’s license."), M("Why is the sister traveling to Manila?", "to be a bridesmaid", ["to study", "to work", "to move"], "abay."), M("When will the sister fly to Manila?", "on Friday", ["on Sunday", "on Saturday", "next year"], "Biyernes."), M("When is the wedding?", "Sunday morning", ["Friday night", "Saturday afternoon", "Monday"], "Linggo ng umaga."), M("How many days will she stay in Manila?", "four", ["two", "seven", "ten"], "apat na araw."), M("When is Georgina leaving?", "on Saturday", ["on Friday", "on Sunday", "next year"], "sa Sabado."), M("What will Ninang Gloria give Georgina?", "money for gifts", ["a plane ticket", "a new passport", "luggage"], "pera.")]
        + [F("Kasalukuyang lumilipad tayo sa ___ na tatlumpu’t tatlong libong talampakan. (altitude)", "taas", ["bilis", "oras"], "taas."), F("Hanapin mo si Romeo Magtalas. ___ ko ’yan sa kasal. (godson)", "Inaanak", ["Ninang", "Kuya"], "inaanak."), F("Siguraduhin mo lang na ___ ang pasaporte mo. (valid)", "balido", ["kulang", "mapaso"], "balido."), F("Hindi bale, dumaan ka na lang dito sa ___. (house)", "bahay", ["paliparan", "opisina"], "bahay.")]
