# ------------------------------------------------------------------ 6 speaking and glossary
_S11 = [("Immigration Officer", "Magandang umaga po. Pakipakita po ang pasaporte at balidong ID ninyo.", "Good morning. Please show your passport and a valid ID."), ("Traveler", "Magandang umaga po. Heto po.", "Good morning. Here you are."), ("Immigration Officer", "Ano po ang pakay ng pagbisita ninyo at saan kayo tutuloy sa Pilipinas?", "What is the purpose of your visit and where will you stay in the Philippines?"), ("Traveler", "Bibisitahin ko po ang mga kamag-anak ko. Tutuloy po ako sa bahay nila sa Lipa, Batangas.", "I will visit my relatives. I will stay at their house in Lipa, Batangas."), ("Immigration Officer", "Gaano po kayo katagal dito sa bansa?", "How long will you stay in the country?"), ("Traveler", "Mga isang buwan po.", "About a month."), ("Immigration Officer", "Kailangan po ninyong kumuha ng bago at balidong pasaporte dahil malapit na pong mapaso ito, pati ang ID ninyo.", "You need to get a new and valid passport because it is about to expire, and your ID as well."), ("Traveler", "Gagawin ko po iyon pagbalik ko sa bansa ko. Salamat po.", "I will do that when I return to my country. Thank you.")]
_S12 = [("Receptionist", "Magandang hapon po, Cebu Pacific po ito. Ano po ang maitutulong ko sa inyo?", "Good afternoon, this is Cebu Pacific. How may I help you?"), ("Passenger", "Magandang hapon po. Ako po si Nonito Pimentel. Nag-uulat po ako ng nawawalang bagahe.", "Good afternoon. I am Nonito Pimentel. I am reporting missing luggage."), ("Receptionist", "Sige po, matutulungan ko kayo. Puwede po bang ulitin ang buong pangalan ninyo, ang flight number, ang petsa at ilan ang bagahe?", "Sure, I can help you. May I ask again for your full name, the flight number, the date and how many bags?"), ("Passenger", "Nonito Pimentel po, flight isa pito walo, Oktubre trenta, at isa lang po ang nawawala.", "Nonito Pimentel, flight one seven eight, October thirtieth, and only one is missing."), ("Receptionist", "Ano po ang itsura ng bagahe?", "What does the luggage look like?"), ("Passenger", "Kulay itim po ito, may tatak na Samsonite at mga dalawang talampakan ang taas.", "It is black, a Samsonite brand and about two feet tall."), ("Receptionist", "Salamat po sa impormasyon. Maghintay po kayo ng ilang segundo at titingnan ko kung nasa opisina namin ang nawawalang bagahe.", "Thank you for the information. Please wait a few seconds and I will check whether the missing luggage is in our office."), ("Passenger", "Walang problema po.", "No problem.")]
