_MT = [("Sa isang taon pa kami bibiyahe sa Pilipinas.", "We will travel to the Philippines not until next year."), ("Magbabakasyon kami sa probinsiya sa susunod na taon.", "We will vacation in the province the following year."), ("Balak naming pumunta ng Europa sa darating na taon.", "We plan to go to Europe this coming year."), ("Sana, magkita tayo balang araw.", "I hope we meet someday."), ("Sa hinaharap po, asikasuhin ninyo nang mas maaga ang pagpapa-renew ng pasaporte ninyo, nang hindi kayo maperwisyo.", "In the future, please take care of renewing your passport earlier, so you won’t be inconvenienced."), ("Naku, Miss, mapapaso na ang inyong pasaporte sa makalawa.", "Oh dear, Miss, your passport will expire the day after tomorrow."), ("Gusto ko pong magpareserba ng kuwarto para sa Biyernes.", "I would like to reserve a room for Friday."), ("Sa linggong darating, papasyal ang mga kamag-anak natin mula sa Hawaii.", "This coming week our relatives will visit from Hawaii.")]
